    border = grid[0] + grid[-1] + [r[0] for r in grid] + [r[-1] for r in grid]
    frame = max(set(border), key=border.count)
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    for c in (0, frame):
        counts.pop(c, None)
    inner = min(counts, key=counts.get)
    outer = max(counts, key=counts.get)

    result = [[frame for _ in range(w)] for _ in range(h)]
    for i in range(1, h-1):
        for j in range(1, w-1):
            result[i][j] = outer

