def transform(grid):
    h = len(grid)
    w = len(grid[0])
    border_cells = []
    for j in range(w):
        border_cells.append(grid[0][j])
        border_cells.append(grid[h-1][j])
    for i in range(h):
        border_cells.append(grid[i][0])
        border_cells.append(grid[i][w-1])
    border_color = max(set(border_cells), key=border_cells.count)

    frequencies = {}
    for row in grid:
        for value in row:
            if value != 0 and value != border_color:
                frequencies[value] = frequencies.get(value, 0) + 1
    inner_color = min(frequencies, key=lambda value: frequencies[value])
    outer_color = max(frequencies, key=lambda value: frequencies[value])

    output = [[border_color for j in range(w)] for i in range(h)]
    for i in range(1, h-1):
        for j in range(1, w-1):
            output[i][j] = outer_color

    for value in [outer_color, inner_color]:
        positions = [(i, j) for i in range(h) for j in range(w)
                     if grid[i][j] == value]
        first_row = min(position[0] for position in positions)
        first_col = min(position[1] for position in positions)
        last_row = max(position[0] for position in positions)
        last_col = max(position[1] for position in positions)
        side = max(last_row-first_row, last_col-first_col) + 1
        for i in range(first_row, first_row+side):
            for j in range(first_col, first_col+side):
                output[i][j] = value
    return output
